1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "membershipNumber",
29	        expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	        expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	        expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality",
35	        expression = "java(locality(owner))")
36	    @Mapping(target = "timezone",
37	        expression = "java(timezone(owner))")
38	    @Mapping(target = "contactPreference",
39	        expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(identityKey(owner))")
42	    @Mapping(target = "checkDigit",
43	        expression = "java(checkDigit(owner))")
44	    @Mapping(target = "ageBand",
45	        expression = "java(ageBand(owner))")
46	    @Mapping(target = "sharesHousehold", ignore = true)
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    /**
50	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
51	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
52	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
53	     * so owners without a birth date serialize cleanly.
54	     */
55	    default String ageBand(Owner owner) {
56	        java.time.LocalDate birthDate = owner.getBirthDate();
57	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
58	        if (birthDate == null || registrationDate == null) {
59	            return null;
60	        }
61	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
62	        if (age < 18) {
63	            return "MINOR";
64	        }
65	        if (age < 65) {
66	            return "ADULT";
67	        }
68	        return "SENIOR";
69	    }
70	
71	    /**
72	     * The E.164 country calling codes whose split from the national number is recognised when
73	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
74	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
75	     */
76	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
77	
78	    /**
79	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
80	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
81	     * country code is split off using the recognised calling codes; when none matches, a single-digit
82	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
83	     * Returns the stored value unchanged when it is null or not in E.164 form.
84	     */
85	    default String telephoneDisplay(Owner owner) {
86	        String telephone = owner.getTelephone();
87	        if (telephone == null || !telephone.startsWith("+")) {
88	            return telephone;
89	        }
90	        String digits = telephone.substring(1);
91	        if (!digits.matches("\\d+")) {
92	            return telephone;
93	        }
94	        String countryCode = digits.substring(0, 1);
95	        String national = digits.substring(1);
96	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
97	            String candidate = digits.substring(0, codeLength);
98	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
99	                countryCode = candidate;
100	                national = digits.substring(codeLength);
101	                break;
102	            }
103	        }
104	        StringBuilder grouped = new StringBuilder();
105	        for (int i = 0; i < national.length(); i++) {
106	            if (i > 0 && i % 3 == 0) {
107	                grouped.append(' ');
108	            }
109	            grouped.append(national.charAt(i));
110	        }
111	        return "+" + countryCode + " " + grouped;
112	    }
113	
114	    /**
115	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
116	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
117	     * serialize cleanly.
118	     */
119	    default Integer checkDigit(Owner owner) {
120	        String customerCode = owner.getCustomerCode();
121	        if (customerCode == null) {
122	            return null;
123	        }
124	        int sum = 0;
125	        boolean dbl = true;
126	        for (int i = customerCode.length() - 1; i >= 0; i--) {
127	            char c = customerCode.charAt(i);
128	            if (c < '0' || c > '9') {
129	                continue;
130	            }
131	            int d = c - '0';
132	            if (dbl) {
133	                d *= 2;
134	                if (d > 9) {
135	                    d -= 9;
136	                }
137	            }
138	            sum += d;
139	            dbl = !dbl;
140	        }
141	        return (10 - (sum % 10)) % 10;
142	    }
143	
144	    /**
145	     * Derive the owner's identity key, the single value into which all duplicate detection is
146	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
147	     * owners are duplicates only when their whole identity keys are equal. A null email or
148	     * householdId contributes an empty segment.
149	     */
150	    default String identityKey(Owner owner) {
151	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
152	        String email = owner.getEmail() == null ? "" : owner.getEmail();
153	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
154	        return telephone + "|" + email + "|" + householdId;
155	    }
156	
157	    /**
158	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
159	     * otherwise 'PHONE'.
160	     */
161	    default String contactPreference(Owner owner) {
162	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
163	        return hasEmail ? "EMAIL" : "PHONE";
164	    }
165	
166	    /**
167	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
168	     * the last two digits of the registrationDate year. Returns null when either source field is
169	     * absent so owners without an assigned code or registration date serialize cleanly.
170	     */
171	    default String membershipNumber(Owner owner) {
172	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
173	            return null;
174	        }
175	        return String.format("%s-M%02d", owner.getCustomerCode(),
176	            owner.getRegistrationDate().getYear() % 100);
177	    }
178	
179	    /**
180	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
181	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
182	     * (householdSize); add 3 for tenure of more than 365 days, measured from the registrationDate to
183	     * the current date. Because a newly created owner has zero tenure, a new owner never earns the
184	     * tenure points.
185	     */
186	    default Integer membershipPoints(Owner owner) {
187	        int points = 0;
188	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
189	        if (hasEmail) {
190	            points += 2;
191	        }
192	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
193	        if (noNamesakes) {
194	            points += 1;
195	        }
196	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
197	            points += 2;
198	        }
199	        if (owner.getRegistrationDate() != null && java.time.temporal.ChronoUnit.DAYS.between(
200	                owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
201	            points += 3;
202	        }
203	        return points;
204	    }
205	
206	    /**
207	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
208	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
209	     */
210	    default Integer membershipLevel(Owner owner) {
211	        int points = membershipPoints(owner);
212	        if (points <= 1) {
213	            return 1;
214	        }
215	        if (points <= 3) {
216	            return 2;
217	        }
218	        if (points <= 5) {
219	            return 3;
220	        }
