363	    private static boolean isBlank(String value) {
364	        return value == null || value.trim().isEmpty();
365	    }
366	
367	    /**
368	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
369	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
370	     * compared case-insensitively with collapsed whitespace.
371	     */
372	    private static String collapse(String value) {
373	        if (value == null) {
374	            return "";
375	        }
376	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
377	    }
378	
379	    /**
380	     * Common street-type abbreviations expanded during address normalization.
381	     */
382	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
383	        "ST", "STREET",
384	        "RD", "ROAD",
385	        "AVE", "AVENUE");
386	
387	    /**
388	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
389	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
390	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
391	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
392	     * address maps to itself.
393	     */
394	    private static String normalizeAddress(String value) {
395	        if (value == null) {
396	            return "";
397	        }
398	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
399	        if (collapsed.isEmpty()) {
400	            return "";
401	        }
402	        String[] tokens = collapsed.split(" ");
403	        StringBuilder sb = new StringBuilder(collapsed.length());
404	        for (int i = 0; i < tokens.length; i++) {
405	            if (i > 0) {
406	                sb.append(' ');
407	            }
408	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
409	        }
410	        return sb.toString();
411	    }
412	
413	    /**
414	     * Derive the stable household identifier shared by owners with the same normalized last name
415	     * and postcode. It is a deterministic function of those two values, so every member of a
416	     * household independently derives the same identifier: the first 12 upper-case hex characters
417	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
418	     * an empty segment.
419	     */
420	    private static String householdId(String normalizedLastName, String postcode) {
421	        try {
422	            byte[] digest = MessageDigest.getInstance("SHA-256")
423	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
424	                    .getBytes(StandardCharsets.UTF_8));
425	            StringBuilder sb = new StringBuilder(digest.length * 2);
426	            for (byte b : digest) {
427	                sb.append(String.format("%02x", b));
428	            }
429	            return sb.substring(0, 12).toUpperCase();
430	        }
431	        catch (NoSuchAlgorithmException e) {
432	            throw new IllegalStateException("SHA-256 not available", e);
433	        }
434	    }
435	
436	    /**
437	     * Derive the identity key into which all duplicate detection is consolidated:
438	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
439	     * household id contributes an empty segment. Two owners are duplicates only when their whole
440	     * identity keys are equal.
441	     */
442	    private static String identityKey(String telephone, String email, String householdId) {
443	        return (telephone == null ? "" : telephone)
444	            + "|" + (email == null ? "" : email)
445	            + "|" + (householdId == null ? "" : householdId);
446	    }
447	
448	    /**
449	     * Count the existing owners that share the given first and last name, compared
450	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
451	     * namesakes that already existed at creation time (the new owner itself is not included).
452	     */
453	    private int countNamesakes(String firstName, String lastName) {
454	        return (int) this.clinicService.findAllOwners().stream()
455	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
456	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
457	                && existing.getLastName().equalsIgnoreCase(lastName))
458	            .count();
459	    }
460	
461	    /**
462	     * Count the existing owners that already belong to the given household (i.e. carry the same
463	     * non-null householdId). Called after any existing members have been backfilled with the shared
464	     * identifier but before the new owner is saved, so the returned value reflects the members that
465	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
466	     * new owner is not part of any household ({@code householdId} is null).
467	     */
468	    private int countHouseholdMembers(String householdId) {
469	        if (householdId == null) {
470	            return 0;
471	        }
472	        return (int) this.clinicService.findAllOwners().stream()
473	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
474	            .count();
475	    }
476	
477	    /**
478	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
479	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
480	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
481	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
482	     * including when the new owner has no last name or postcode, since a shared postcode is required
483	     * to match.
484	     */
485	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
486	        if (isBlank(lastName) || isBlank(postcode)) {
487	            return null;
488	        }
489	        return this.clinicService.findAllOwners().stream()
490	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
491	            .filter(existing -> postcode.equals(existing.getPostcode()))
492	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
493	            .min(java.util.Comparator.comparing(Owner::getId))
494	            .orElse(null);
495	    }
496	
497	    /**
498	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
499	     * request to create another owner in it is rejected as a conflict.
500	     */
501	    private static final int MAX_OWNERS_PER_CITY = 50;
502	
503	    /**
504	     * Count the existing owners registered in the given city, compared case-insensitively (as in
505	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
506	     * reflects the owners that already existed at creation time.
507	     */
508	    private int countOwnersInCity(String city) {
509	        return (int) this.clinicService.findAllOwners().stream()
510	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
511	            .count();
512	    }
513	
514	    /**
515	     * The maximum number of owners that may be created on a single day. Once this many owners
516	     * already carry a given day's registration date, a request to create another owner that day is
517	     * rejected with a 429.
518	     */
519	    private static final int MAX_OWNERS_PER_DAY = 100;
520	
521	    /**
522	     * The number of owners that may be created on a single day before the bulk-signup warning is
523	     * flagged. Once more than this many owners already carry a given day's registration date, a
524	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
525	     */
526	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
527	
528	    /**
529	     * Count the existing owners whose registration date is the given day. Called before the new
530	     * owner is saved, so the returned value reflects the owners that already existed at creation
531	     * time.
532	     */
533	    private int countOwnersRegisteredOn(LocalDate date) {
534	        return (int) this.clinicService.findAllOwners().stream()
535	            .filter(existing -> date.equals(existing.getRegistrationDate()))
536	            .count();
537	    }
538	
539	    /**
540	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
541	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
542	     * supplied or defaulted) always falls on a business day.
543	     */
544	    private static LocalDate toBusinessDay(LocalDate date) {
545	        return switch (date.getDayOfWeek()) {
546	            case SATURDAY -> date.plusDays(2);
547	            case SUNDAY -> date.plusDays(1);
548	            default -> date;
549	        };
550	    }
551	
552	    /**
553	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
554	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
555	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
556	     */
557	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
558	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
559	    }
560	
561	    /**
562	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
563	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
564	     * {@code n} of 2 or more that produces a value no existing owner already carries.
565	     */
566	    private String deduplicateCustomerCode(String base) {
567	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
568	            .map(Owner::getCustomerCode)
569	            .filter(java.util.Objects::nonNull)
570	            .collect(java.util.stream.Collectors.toSet());
571	        if (!inUse.contains(base)) {
572	            return base;
573	        }
574	        int n = 2;
575	        while (inUse.contains(base + "-" + n)) {
576	            n++;
577	        }
578	        return base + "-" + n;
579	    }
580	
581	    /**
582	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
583	     */
584	    private static String hash8(String input) {
585	        try {
586	            byte[] digest = MessageDigest.getInstance("SHA-256")
587	                .digest(input.getBytes(StandardCharsets.UTF_8));
588	            StringBuilder sb = new StringBuilder(digest.length * 2);
589	            for (byte b : digest) {
590	                sb.append(String.format("%02x", b));
591	            }
592	            return sb.substring(0, 8).toUpperCase();
593	        }
594	        catch (NoSuchAlgorithmException e) {
595	            throw new IllegalStateException("SHA-256 not available", e);
596	        }
597	    }
598	
599	    /**
600	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
601	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
602	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
603	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
604	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
605	     * always agree.
606	     */
607	    private static String deriveRegion(String postcode, String city) {
608	        if (postcode != null && postcode.matches("\\d{4}")) {
609	            int value = Integer.parseInt(postcode);
610	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
611	                int[] range = entry.getValue();
612	                if (value >= range[0] && value <= range[1]) {
613	                    return entry.getKey();
614	                }
615	            }
616	        }
617	        if (city == null) {
618	            return "UNKNOWN";
619	        }
620	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
621	    }
622	
623	    /**
624	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
625	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
626	     * and accepts any 4-digit postcode.
627	     */
628	    private static final Map<String, String> CITY_REGION = Map.of(
629	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
630	
631	    /**
632	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
633	     * Each entry is a two-element {@code {low, high}} array.
634	     */
635	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
636	        "NSW", new int[] {2000, 2099},
637	        "VIC", new int[] {3000, 3099},
638	        "QLD", new int[] {4000, 4099});
639	
640	    /**
641	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
642	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
643	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
644	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
645	     * 4-digit postcode. A malformed or out-of-range postcode throws an
646	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
647	     */
648	    private static void validatePostcode(String city, String postcode) {
649	        if (postcode == null || postcode.isEmpty()) {
650	            return;
651	        }
652	        if (!postcode.matches("\\d{4}")) {
653	            throw new InvalidOwnerFieldsException(List.of("postcode"));
654	        }
655	        String region = city == null ? null : CITY_REGION.get(city);
656	        if (region == null) {
657	            return;
658	        }
659	        int[] range = REGION_POSTCODES.get(region);
660	        int value = Integer.parseInt(postcode);
661	        if (value < range[0] || value > range[1]) {
662	            throw new InvalidOwnerFieldsException(List.of("postcode"));
663	        }
664	    }
665	
666	    /**
667	     * Required national-number length for each E.164 country calling code we validate: a
668	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
669	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
670	     */
671	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
672	        "1", 10,
673	        "61", 9);
674	
675	    /**
676	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
677	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
678	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
679	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
680	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
681	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
682	     * rejected with a 400.
683	     */
684	    private static String toE164(String raw) {
685	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
686	        boolean hasCountryCode = cleaned.startsWith("+");
687	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
688	        if (!digits.matches("\\d+")) {
689	            throw new InvalidOwnerFieldsException(List.of("telephone"));
690	        }
691	        if (!hasCountryCode) {
692	            if (digits.startsWith("0")) {
693	                digits = digits.substring(1);
694	            }
695	            digits = "61" + digits;
696	        }
697	        if (digits.length() < 8 || digits.length() > 15) {
698	            throw new InvalidOwnerFieldsException(List.of("telephone"));
699	        }
700	        // For a recognised country code, the national number (the digits after the code) must be
701	        // exactly the expected length for that country. Match the longest known code so a shorter
702	        // code that is a prefix of another cannot mask it.
703	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
704	            if (digits.length() <= codeLength) {
705	                continue;
706	            }
707	            String countryCode = digits.substring(0, codeLength);
708	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
709	            if (requiredNationalLength != null) {
710	                if (digits.length() - codeLength != requiredNationalLength) {
711	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
712	                }
713	                break;
714	            }
715	        }
716	        return "+" + digits;
717	    }
718	
719	    /**
720	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
721	     * and a domain with at least one dot-separated label, none of which contain whitespace or
722	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
723	     */
724	    private static final Pattern EMAIL_PATTERN =
725	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
726	
727	    /**
728	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
729	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
730	     */
731	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
732	        "mailinator.com", "tempmail.com", "guerrillamail.com");
733	
734	    /**
735	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
736	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
737	     * domain is not on the disposable-domain blocklist, otherwise an
738	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
739	     * address is returned lower-cased.
740	     */
741	    private static String normalizeEmail(String email) {
742	        if (email == null || email.isEmpty()) {
743	            return null;
744	        }
745	        String trimmed = email.trim();
746	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
747	            throw new InvalidOwnerFieldsException(List.of("email"));
748	        }
749	        String normalized = trimmed.toLowerCase();
750	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
751	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
752	            throw new InvalidOwnerFieldsException(List.of("email"));
753	        }
754	        return normalized;
755	    }
756	}
